/// Mounts follow `--extern`s, each followed by what it depends on (which rustc reads too,
/// though not named: 77% of the corpus' mounts), and a crate depended on twice is built and
/// written once. (corpus: regex, hundreds of `rmeta > so > rmeta`)
#[test]
fn a_diamond() {
    const MEMCHR: &str = "0a0a0a0a0a0a0a0a";
    const SYNTAX: &str = "0b0b0b0b0b0b0b0b";
    const AHO: &str = "0c0c0c0c0c0c0c0c";
    const AUTOMATA: &str = "0d0d0d0d0d0d0d0d";
    let t = Tree::new();
    t.lib("memchr", "2.7.4", MEMCHR, vec![]);
    t.lib("regex-syntax", "0.8.5", SYNTAX, vec![]);
    t.lib("aho-corasick", "1.1.3", AHO, vec![ext("memchr", MEMCHR, "rmeta")]);
    let deps = || {
        vec![
            ext("aho_corasick", AHO, "rmeta"),
            ext("memchr", MEMCHR, "rmeta"),
            ext("regex_syntax", SYNTAX, "rmeta"),
        ]
    };
    t.lib("regex-automata", "0.4.9", AUTOMATA, deps());
    // Not memchr: it is mounted all the same, for rustc reads its metadata through the others'
    let externs = vec![
        ext("aho_corasick", AHO, "rmeta"),
        ext("regex_automata", AUTOMATA, "rmeta"),
        ext("regex_syntax", SYNTAX, "rmeta"),
    ];
    let regex = t.lib("regex", "1.11.1", "0e0e0e0e0e0e0e0e", externs);
    for (needle, count) in [
        ("FROM scratch AS cratesio-memchr-2.7.4\n", 1),
        ("FROM rust-base AS dep-n-memchr-2.7.4-", 1),
        ("FROM rust-base AS dep-n-aho-corasick-1.1.3-", 1),
    ] {
        assert_eq!(regex.matches(needle).count(), count, "{needle:?} in {regex}");
    }
    assert_snapshots_eq!(
        mounts(&regex, "dep-n-regex-1"),
        snapbox::str![[r#"
  --mount=from=cratesio-regex-1.11.1,source=/regex-1.11.1,dst=$CARGO_HOME/registry/src/index.crates.io/regex-1.11.1
  --mount=from=out-0c0c0c0c0c0c0c0c,dst=/target/debug/deps/libaho_corasick-0c0c0c0c0c0c0c0c.rmeta,source=/deps/libaho_corasick-0c0c0c0c0c0c0c0c.rmeta
  --mount=from=out-0a0a0a0a0a0a0a0a,dst=/target/debug/deps/libmemchr-0a0a0a0a0a0a0a0a.rmeta,source=/deps/libmemchr-0a0a0a0a0a0a0a0a.rmeta
  --mount=from=out-0d0d0d0d0d0d0d0d,dst=/target/debug/deps/libregex_automata-0d0d0d0d0d0d0d0d.rmeta,source=/deps/libregex_automata-0d0d0d0d0d0d0d0d.rmeta
  --mount=from=out-0b0b0b0b0b0b0b0b,dst=/target/debug/deps/libregex_syntax-0b0b0b0b0b0b0b0b.rmeta,source=/deps/libregex_syntax-0b0b0b0b0b0b0b0b.rmeta

"#]]
    );
}

/// A crate built as `cdylib` and `rlib` emits no `.rmeta`, so its `.rlib` is mounted
/// among others' `.rmeta`s. (corpus: ntpd's rustls-platform-verifier)
#[test]
fn an_rlib_without_metadata() {
    const MEMCHR: &str = "3a3a3a3a3a3a3a3a";
    const VERIFIER: &str = "3b3b3b3b3b3b3b3b";
    let t = Tree::new();
    t.lib("memchr", "2.7.4", MEMCHR, vec![]);
    let (pkg, version) = ("rustls-platform-verifier", "0.5.3");
    let crate_types = &["cdylib", "rlib"][..];
    t.compile(Krate { pkg, version, mdid: VERIFIER, crate_types, ..Default::default() });
    assert_snapshots_eq!(
        t.md(VERIFIER),
        snapbox::str![[r#"
stamp = 2
this = "3b3b3b3b3b3b3b3b"
writes = [
    "librustls_platform_verifier-3b3b3b3b3b3b3b3b.so",
    "librustls_platform_verifier-3b3b3b3b3b3b3b3b.rlib",
    "rustls_platform_verifier-3b3b3b3b3b3b3b3b.d",
]

"#]]
    );
    let externs =
        vec![ext("memchr", MEMCHR, "rmeta"), ext("rustls_platform_verifier", VERIFIER, "rlib")];
    let ntp_proto = t.lib("ntp-proto", "1.7.1", "3c3c3c3c3c3c3c3c", externs);
    assert_snapshots_eq!(
        mounts(&ntp_proto, "dep-n-ntp-proto"),
        snapbox::str![[r#"
  --mount=from=cratesio-ntp-proto-1.7.1,source=/ntp-proto-1.7.1,dst=$CARGO_HOME/registry/src/index.crates.io/ntp-proto-1.7.1
  --mount=from=out-3a3a3a3a3a3a3a3a,dst=/target/debug/deps/libmemchr-3a3a3a3a3a3a3a3a.rmeta,source=/deps/libmemchr-3a3a3a3a3a3a3a3a.rmeta
  --mount=from=out-3b3b3b3b3b3b3b3b,dst=/target/debug/deps/librustls_platform_verifier-3b3b3b3b3b3b3b3b.rlib,source=/deps/librustls_platform_verifier-3b3b3b3b3b3b3b3b.rlib

"#]]
    );
}

/// Cross-compiling: target crates live under `target/<triple>/`, while proc-macros and build
/// scripts are host executables, under the host's `target/`. A build script runs to write
/// under the target's, from which target crates then take its `$OUT_DIR` and `.rmeta`s.
/// (corpus: marauder's anyhow, for armv7)
#[test]
fn cross_compiling_a_build_script() {
    const TRIPLE: &str = "armv7-unknown-linux-musleabihf";
    const BUILT: &str = "4a4a4a4a4a4a4a4a";
    const RUN: &str = "4b4b4b4b4b4b4b4b";
    const ANYHOW: &str = "4c4c4c4c4c4c4c4c";
    let t = Tree::new();
    let (pkg, version, target) = ("anyhow", "1.0.100", Some(TRIPLE));
    t.buildrs(Krate { pkg, version, mdid: BUILT, ..Default::default() });
    let vars = &[("TARGET", TRIPLE), ("HOST", "x86_64-unknown-linux-gnu")];
    let run = t.run(Run {
        pkg,
        version,
        built: BUILT,
        mdid: RUN,
        target,
        vars,
        writes: &["out/x"],
        ..Default::default()
    });
    assert_snapshots_eq!(
        brief(stage(&run, "run-z-anyhow")),
        snapbox::str![[r#"
FROM rust-base AS run-z-anyhow-1.0.100-4b4b4b4b4b4b4b4b
WORKDIR /target/armv7-unknown-linux-musleabihf/debug/build/anyhow-4b4b4b4b4b4b4b4b/out
WORKDIR $CARGO_HOME/registry/src/index.crates.io/anyhow-1.0.100
RUN \
  --mount=from=out-4a4a4a4a4a4a4a4a,source=/anyhow-4a4a4a4a4a4a4a4a/_build_script_build-4a4a4a4a4a4a4a4a,dst=/target/debug/build/anyhow-4a4a4a4a4a4a4a4a/build-script-build \
  --mount=from=cratesio-anyhow-1.0.100,source=/anyhow-1.0.100,dst=$CARGO_HOME/registry/src/index.crates.io/anyhow-1.0.100 \
  <<'EOR'
export \
  CARGO_MANIFEST_DIR=$CARGO_HOME/registry/src/index.crates.io/anyhow-1.0.100 \
  CARGO_PKG_NAME=anyhow \
  CARGO_PKG_VERSION=1.0.100 \
  HOST=x86_64-unknown-linux-gnu \
  OUT_DIR=/target/armv7-unknown-linux-musleabihf/debug/build/anyhow-4b4b4b4b4b4b4b4b/out \
  TARGET=armv7-unknown-linux-musleabihf \
  CARGOGREEN=1
/target/debug/build/anyhow-4a4a4a4a4a4a4a4a/build-script-build \
  1>/target/armv7-unknown-linux-musleabihf/debug/build/anyhow-4b4b4b4b4b4b4b4b/stdout 2>/target/armv7-unknown-linux-musleabihf/debug/build/anyhow-4b4b4b4b4b4b4b4b/stderr || echo $? >/target/armv7-unknown-linux-musleabihf/debug/build/anyhow-4b4b4b4b4b4b4b4b/stdcode
find /target/armv7-unknown-linux-musleabihf/debug/build/anyhow-4b4b4b4b4b4b4b4b/out/ /target/armv7-unknown-linux-musleabihf/debug/build/anyhow-4b4b4b4b4b4b4b4b/std* -exec touch --no-dereference --date=@$SOURCE_DATE_EPOCH '{}' +
EOR

"#]]
    );

    let out_dir = format!("{}/build/anyhow-{RUN}/out", t.host.profile(target));
    t.compile(Krate {
        pkg,
        version,
        mdid: ANYHOW,
        target,
        vars: &[("OUT_DIR", &out_dir)],
        ..Default::default()
    });
    // Proc-macros are built for the host
    t.proc_macro("num-derive", "0.3.3", "4e4e4e4e4e4e4e4e", vec![]);
    let marauder = t.compile(Krate {
        pkg: "marauder",
        version: "0.5.0",
        mdid: "4d4d4d4d4d4d4d4d",
        target,
        externs: vec![
            format!("anyhow={}/deps/libanyhow-{ANYHOW}.rmeta", t.host.profile(target)),
            ext("num_derive", "4e4e4e4e4e4e4e4e", "so"),
        ],
        args: "-C linker=arm-linux-gnueabihf-gcc".into(),
        ..Default::default()
    });
    assert_snapshots_eq!(
        mounts(&marauder, "dep-n-marauder"),
        snapbox::str![[r#"
  --mount=from=cratesio-marauder-0.5.0,source=/marauder-0.5.0,dst=$CARGO_HOME/registry/src/index.crates.io/marauder-0.5.0
  --mount=from=out-4c4c4c4c4c4c4c4c,dst=/target/armv7-unknown-linux-musleabihf/debug/deps/libanyhow-4c4c4c4c4c4c4c4c.rmeta,source=/deps/libanyhow-4c4c4c4c4c4c4c4c.rmeta
  --mount=from=out-4e4e4e4e4e4e4e4e,dst=/target/debug/deps/libnum_derive-4e4e4e4e4e4e4e4e.so,source=/deps/libnum_derive-4e4e4e4e4e4e4e4e.so
  --mount=from=out-4b4b4b4b4b4b4b4b,source=/out,dst=/target/armv7-unknown-linux-musleabihf/debug/build/anyhow-4b4b4b4b4b4b4b4b/out

"#]]
    );
}

/// Git crates compile from their checkout's root, mounted whole, wherever they sit in it,
/// and their build scripts run from their own dir. (corpus: marauder's pb, CreuSAT at the
/// root, cargo-osdk's members 3 levels deep)
#[test]
fn git_crates() {
    const BUILT: &str = "5a5a5a5a5a5a5a5a";
    const RUN: &str = "5b5b5b5b5b5b5b5b";
    let t = Tree::new();
    let (pkg, version, src) = ("pb", "0.5.0", Src::Git("pb"));
    let built = t.buildrs(Krate { pkg, version, mdid: BUILT, src, ..Default::default() });
    assert_snapshots_eq!(
        brief(stage(&built, "dep-x-pb")),
        snapbox::str![[r#"
FROM rust-base AS dep-x-pb-0.5.0-5a5a5a5a5a5a5a5a
WORKDIR /target/debug/build/pb-5a5a5a5a5a5a5a5a
WORKDIR $CARGO_HOME/git/checkouts/remarkable-tools-9f4e9942cc4e93a3/268a3ad
RUN \
  --mount=from=checkout-268a3ad-268a3ad78f33f306d308d1b1372d655215e160b2,dst=$CARGO_HOME/git/checkouts/remarkable-tools-9f4e9942cc4e93a3/268a3ad \
  <<'EOR'
export \
  CARGO_CRATE_NAME=build_script_build \
  CARGO_MANIFEST_DIR=$CARGO_HOME/git/checkouts/remarkable-tools-9f4e9942cc4e93a3/268a3ad/pb \
  CARGO_PKG_NAME=pb \
  CARGO_PKG_VERSION=0.5.0 \
  CARGOGREEN=1
rustc --crate-name build_script_build --crate-type bin --edition 2021 --emit dep-info,link --out-dir /target/debug/build/pb-5a5a5a5a5a5a5a5a -C extra-filename=-5a5a5a5a5a5a5a5a -L dependency=/target/debug/deps pb/build.rs \
  1>/target/debug/build/pb-5a5a5a5a5a5a5a5a/../stdout 2>/target/debug/build/pb-5a5a5a5a5a5a5a5a/../stderr || echo $? >/target/debug/build/pb-5a5a5a5a5a5a5a5a/../stdcode
mv /target/debug/build/pb-5a5a5a5a5a5a5a5a/build_script_build-5a5a5a5a5a5a5a5a /target/debug/build/pb-5a5a5a5a5a5a5a5a/_build_script_build-5a5a5a5a5a5a5a5a
printf '#!/bin/sh\nenv CARGOGREEN_EXECUTEBUILDSCRIPT=$0 cargo-green\n' >/target/debug/build/pb-5a5a5a5a5a5a5a5a/build_script_build-5a5a5a5a5a5a5a5a
chmod +x /target/debug/build/pb-5a5a5a5a5a5a5a5a/build_script_build-5a5a5a5a5a5a5a5a
find /target/debug/build/pb-5a5a5a5a5a5a5a5a/ /target/debug/build/pb-5a5a5a5a5a5a5a5a/../std* \( -name '*-5a5a5a5a5a5a5a5a*' -o -name 'std*' \) -exec touch --no-dereference --date=@$SOURCE_DATE_EPOCH '{}' +
EOR

"#]]
    );
    let writes = &["out/pb.rs"];
    let run =
        t.run(Run { pkg, version, built: BUILT, mdid: RUN, src, writes, ..Default::default() });
    assert_snapshots_eq!(
        brief(stage(&run, "run-z-pb")),
        snapbox::str![[r#"
FROM rust-base AS run-z-pb-0.5.0-5b5b5b5b5b5b5b5b
WORKDIR /target/debug/build/pb-5b5b5b5b5b5b5b5b/out
WORKDIR $CARGO_HOME/git/checkouts/remarkable-tools-9f4e9942cc4e93a3/268a3ad/pb
RUN \
  --mount=from=out-5a5a5a5a5a5a5a5a,source=/pb-5a5a5a5a5a5a5a5a/_build_script_build-5a5a5a5a5a5a5a5a,dst=/target/debug/build/pb-5a5a5a5a5a5a5a5a/build-script-build \
  --mount=from=checkout-268a3ad-268a3ad78f33f306d308d1b1372d655215e160b2,dst=$CARGO_HOME/git/checkouts/remarkable-tools-9f4e9942cc4e93a3/268a3ad \
  <<'EOR'
export \
  CARGO_MANIFEST_DIR=$CARGO_HOME/git/checkouts/remarkable-tools-9f4e9942cc4e93a3/268a3ad/pb \
  CARGO_PKG_NAME=pb \
  CARGO_PKG_VERSION=0.5.0 \
  OUT_DIR=/target/debug/build/pb-5b5b5b5b5b5b5b5b/out \
  CARGOGREEN=1
/target/debug/build/pb-5a5a5a5a5a5a5a5a/build-script-build \
  1>/target/debug/build/pb-5b5b5b5b5b5b5b5b/stdout 2>/target/debug/build/pb-5b5b5b5b5b5b5b5b/stderr || echo $? >/target/debug/build/pb-5b5b5b5b5b5b5b5b/stdcode
find /target/debug/build/pb-5b5b5b5b5b5b5b5b/out/ /target/debug/build/pb-5b5b5b5b5b5b5b5b/std* -exec touch --no-dereference --date=@$SOURCE_DATE_EPOCH '{}' +
EOR

"#]]
    );
    let out_dir = format!("{DEBUG}/build/pb-{RUN}/out");
    let vars = &[("OUT_DIR", out_dir.as_str())];
    let pb = t.compile(Krate {
        pkg,
        version,
        mdid: "5c5c5c5c5c5c5c5c",
        src,
        vars,
        ..Default::default()
    });
    assert_snapshots_eq!(
        brief(stage(&pb, "dep-n-pb")),
        snapbox::str![[r#"
FROM rust-base AS dep-n-pb-0.5.0-5c5c5c5c5c5c5c5c
WORKDIR /target/debug/deps
WORKDIR $CARGO_HOME/git/checkouts/remarkable-tools-9f4e9942cc4e93a3/268a3ad
RUN \
  --mount=from=checkout-268a3ad-268a3ad78f33f306d308d1b1372d655215e160b2,dst=$CARGO_HOME/git/checkouts/remarkable-tools-9f4e9942cc4e93a3/268a3ad \
  --mount=from=out-5b5b5b5b5b5b5b5b,source=/out,dst=/target/debug/build/pb-5b5b5b5b5b5b5b5b/out \
  <<'EOR'
export \
  CARGO_CRATE_NAME=pb \
  CARGO_MANIFEST_DIR=$CARGO_HOME/git/checkouts/remarkable-tools-9f4e9942cc4e93a3/268a3ad/pb \
  CARGO_PKG_NAME=pb \
  CARGO_PKG_VERSION=0.5.0 \
  OUT_DIR=/target/debug/build/pb-5b5b5b5b5b5b5b5b/out \
  CARGOGREEN=1
rustc --crate-name pb --crate-type lib --edition 2021 --emit dep-info,metadata,link --out-dir /target/debug/deps -C extra-filename=-5c5c5c5c5c5c5c5c -L dependency=/target/debug/deps pb/src/lib.rs \
  1>/target/debug/stdout 2>/target/debug/stderr || echo $? >/target/debug/stdcode
find /target/debug/deps/ /target/debug/std* \( -name '*-5c5c5c5c5c5c5c5c*' -o -name 'std*' \) -exec touch --no-dereference --date=@$SOURCE_DATE_EPOCH '{}' +
EOR

"#]]
    );

    for (src, pkg, checkout) in [
        (Src::Git(""), "remarkable-tools", "checkout-remarkable-tools-9f4e9942cc4e93a3-"),
        (Src::Git("ostd/libs/align_ext"), "align_ext", "checkout-libs-"),
    ] {
        let version = "0.1.0";
        let k = Krate { pkg, version, mdid: "5d5d5d5d5d5d5d5d", src, ..Default::default() };
        let containerfile = t.compile(k);
        let own = stage(&containerfile, &format!("dep-n-{pkg}-"));
        assert!(own.contains(&format!("  --mount=from={checkout}")), "{own}");
        let root =
            "\nWORKDIR $CARGO_HOME/git/checkouts/remarkable-tools-9f4e9942cc4e93a3/268a3ad\n";
        assert!(own.contains(root), "{own}");
    }
}

/// A build script gets the `$OUT_DIR`s its dependencies' own build scripts wrote.
/// (corpus: alacritty's glutin_egl_sys, tract-linalg)
#[test]
fn a_build_script_mounting_out_dirs() {
    let t = Tree::new();
    t.grow_num_traits();
    let built = t.buildrs(Krate {
        pkg: "num-integer",
        version: "0.1.44",
        mdid: "6a6a6a6a6a6a6a6a",
        externs: vec![ext("num_traits", NUM_TRAITS, "rlib")],
        ..Default::default()
    });
    assert_snapshots_eq!(
        mounts(&built, "dep-x-num-integer"),
        snapbox::str![[r#"
  --mount=from=cratesio-num-integer-0.1.44,source=/num-integer-0.1.44,dst=$CARGO_HOME/registry/src/index.crates.io/num-integer-0.1.44
  --mount=from=out-4444444444444444,dst=/target/debug/deps/libnum_traits-4444444444444444.rlib,source=/deps/libnum_traits-4444444444444444.rlib
  --mount=from=out-3333333333333333,source=/out,dst=/target/debug/build/num-traits-3333333333333333/out

"#]]
    );
}

/// A build script may use a proc-macro, mounted as a dylib. (corpus: bottom, slog-try)
#[test]
fn a_build_script_using_a_proc_macro() {
    const NUM_DERIVE: &str = "7a7a7a7a7a7a7a7a";
    let t = Tree::new();
    let (pkg, version) = ("num-derive", "0.3.3");
    t.compile(Krate {
        pkg,
        version,
        mdid: NUM_DERIVE,
        crate_types: &["proc-macro"],
        ..Default::default()
    });
    let built = t.buildrs(Krate {
        pkg: "bottom",
        version: "0.11.4",
        mdid: "7b7b7b7b7b7b7b7b",
        externs: vec![ext("num_derive", NUM_DERIVE, "so")],
        ..Default::default()
    });
    assert_snapshots_eq!(
        mounts(&built, "dep-x-bottom"),
        snapbox::str![[r#"
  --mount=from=cratesio-bottom-0.11.4,source=/bottom-0.11.4,dst=$CARGO_HOME/registry/src/index.crates.io/bottom-0.11.4
  --mount=from=out-7a7a7a7a7a7a7a7a,dst=/target/debug/deps/libnum_derive-7a7a7a7a7a7a7a7a.so,source=/deps/libnum_derive-7a7a7a7a7a7a7a7a.so

"#]]
    );
}

/// The package being installed has its build script compiled as primary too, which then
/// writes a recipe. (corpus: alacritty, bottom)
#[test]
fn the_primary_package_s_build_script() {
    let mut t = Tree::new();
    t.experiments.clear();
    let built = t.buildrs(Krate {
        pkg: "alacritty",
        version: "0.17.0",
        mdid: "8a8a8a8a8a8a8a8a",
        vars: &[("CARGO_PRIMARY_PACKAGE", "1")],
        ..Default::default()
    });
    assert_snapshots_eq!(
        envs(&built, "dep-x-alacritty"),
        snapbox::str![[r#"
export \
  CARGO_CRATE_NAME=build_script_build \
  CARGO_MANIFEST_DIR=$CARGO_HOME/registry/src/index.crates.io/alacritty-0.17.0 \
  CARGO_PKG_NAME=alacritty \
  CARGO_PKG_VERSION=0.17.0 \
  CARGO_PRIMARY_PACKAGE=1 \
  CARGOGREEN=1

"#]]
    );
    assert_snapshots_eq!(
        recipe_tail(&t),
        snapbox::str![[r#"
 this file to:
# DOCKER_BUILDKIT="1" \
#   docker buildx build --target=out-8a8a8a8a8a8a8a8a <THIS_FILE

FROM scratch
COPY --link --from=out-8a8a8a8a8a8a8a8a /alacritty-8a8a8a8a8a8a8a8a/build_script_build-8a8a8a8a8a8a8a8a /build-script-build

"#]]
    );
}

/// A build script's output is kept in its Md as it ran, in the container, and reaches cargo
/// with host paths. Cargo turns it into rustc flags for the crate, which get remapped once
/// more: `-L native` into the mounted `$OUT_DIR`, system paths untouched.
/// (corpus: ring's `-L native=…/out`, 345 times)
#[test]
fn a_native_library_round_trip() {
    const BUILT: &str = "0f0f0f0f0f0f0f0f";
    const RUN: &str = "f0f0f0f0f0f0f0f0";
    let t = Tree::new();
    let (pkg, version) = ("ring", "0.17.8");
    t.buildrs(Krate { pkg, version, mdid: BUILT, ..Default::default() });
    t.run(Run {
        pkg,
        version,
        built: BUILT,
        mdid: RUN,
        writes: &["out/libring_core_0_17_8_.a"],
        stdout: &[
            "cargo:rustc-link-lib=static=ring_core_0_17_8_",
            "cargo:rustc-link-search=native=/target/debug/build/ring-f0f0f0f0f0f0f0f0/out",
            "cargo:rustc-link-search=native=/usr/lib/x86_64-linux-gnu",
            "cargo:rustc-link-lib=z",
        ],
        ..Default::default()
    });
    assert_snapshots_eq!(
        t.md(RUN),
        snapbox::str![[r#"
stamp = 2
this = "f0f0f0f0f0f0f0f0"
deps = ["0f0f0f0f0f0f0f0f"]
writes_to = "/target/debug/build/ring-f0f0f0f0f0f0f0f0/out"
writes = ["out/libring_core_0_17_8_.a"]
stdout = [
    "cargo:rustc-link-lib=static=ring_core_0_17_8_",
    "cargo:rustc-link-search=native=/target/debug/build/ring-f0f0f0f0f0f0f0f0/out",
    "cargo:rustc-link-search=native=/usr/lib/x86_64-linux-gnu",
    "cargo:rustc-link-lib=z",
]

"#]]
    );
    let to_cargo = t.cargo.read(Stdout);
    assert_snapshots_eq!(
        to_cargo.join("\n"),
        snapbox::str![[r#"
cargo:rustc-link-lib=static=ring_core_0_17_8_
cargo:rustc-link-search=native=/home/u/mycrate/target/debug/build/ring-f0f0f0f0f0f0f0f0/out
cargo:rustc-link-search=native=/usr/lib/x86_64-linux-gnu
cargo:rustc-link-lib=z
"#]]
    );

    // What cargo makes of it
    let args: Vec<_> = to_cargo
        .iter()
        .filter_map(|l| {
            let (key, val) = l.strip_prefix("cargo:rustc-link-")?.split_once('=')?;
            Some(format!("-{} {val}", if key == "lib" { 'l' } else { 'L' }))
        })
        .collect();
    let out_dir = format!("{DEBUG}/build/ring-{RUN}/out");
    let ring = t.compile(Krate {
        pkg,
        version,
        mdid: "e0e0e0e0e0e0e0e0",
        vars: &[("OUT_DIR", &out_dir)],
        args: args.join(" "),
        ..Default::default()
    });
    assert_snapshots_eq!(
        rustc(&ring, "dep-n-ring"),
        snapbox::str![
            "rustc --crate-name ring --crate-type lib --edition 2021 --emit dep-info,metadata,link --out-dir /target/debug/deps -C extra-filename=-e0e0e0e0e0e0e0e0 -L dependency=/target/debug/deps -L native=/target/debug/build/ring-f0f0f0f0f0f0f0f0/out -L native=/usr/lib/x86_64-linux-gnu -l static=ring_core_0_17_8_ -l z $CARGO_HOME/registry/src/index.crates.io/ring-0.17.8/src/lib.rs"
        ]
    );
}

/// rustc's diagnostics are kept in the Md, then reach cargo with host paths: the target
/// dir's, the crate's sources', `$CARGO_HOME`'s.
#[test]
fn rustc_diagnostics_reach_cargo_with_host_paths() {
    let t = Tree::new();
    t.compile(Krate {
        pkg: "mycrate",
        version: "0.1.0",
        mdid: MYCRATE,
        src: Src::Local,
        crate_types: &["bin"],
        stderr: &[
            r#"{"$message_type":"artifact","artifact":"/target/debug/deps/mycrate-5555555555555555","emit":"link"}"#,
            r#"{"$message_type":"diagnostic","message":"unused variable: `x`","spans":[{"file_name":"/work/src/main.rs"}],"rendered":"warning: unused variable: `x`\n --> /work/src/main.rs:1:13\n"}"#,
            r#"{"$message_type":"diagnostic","message":"in a dependency","spans":[{"file_name":"/usr/local/cargo/registry/src/index.crates.io/memchr-2.7.4/src/lib.rs"}]}"#,
        ],
        ..Default::default()
    });
    assert_eq!(t.cargo.read(Stdout), [""; 0]);
    assert_snapshots_eq!(
        t.cargo.read(Stderr).join("\n"),
        snapbox::str![[r#"
{"$message_type":"artifact","artifact":"/home/u/mycrate/target/debug/deps/mycrate-5555555555555555","emit":"link"}
{"$message_type":"diagnostic","message":"unused variable: `x`","spans":[{"file_name":"/home/u/mycrate/src/main.rs"}],"rendered":"warning: unused variable: `x`\n --> /home/u/mycrate/src/main.rs:1:13\n"}
{"$message_type":"diagnostic","message":"in a dependency","spans":[{"file_name":"/home/u/.cargo/registry/src/index.crates.io/memchr-2.7.4/src/lib.rs"}]}
"#]]
    );
}

/// rustc's complaints are rewritten into hints at what to configure: a missing system
/// library, a variable needed at compile time. (corpus: diesel_cli's `-lpq`, mime_guess)
#[test]
fn rustc_errors_come_with_hints() {
    let t = Tree::new();
    t.compile(Krate {
        pkg: "diesel_cli",
        version: "2.3.4",
        mdid: "d1d1d1d1d1d1d1d1",
        crate_types: &["bin"],
        stderr: &[
            r#"{"$message_type":"diagnostic","rendered":"error: linking with `cc` failed\n  = note: /usr/bin/ld: cannot find -lpq: No such file or directory\n"}"#,
            r#"{"$message_type":"diagnostic","rendered":"error: environment variable `MIME_TYPES_GENERATED_PATH` not defined at compile time\n  = help: use `std::env::var(\"MIME_TYPES_GENERATED_PATH\")` to read the variable at run time\n"}"#,
        ],
        ..Default::default()
    });
    assert_snapshots_eq!(
        t.cargo.read(Stderr).join("\n"),
        snapbox::str![[r#"
{"$message_type":"diagnostic","rendered":"error: linking with `cc` failed\n  = note: /usr/bin/ld: cannot find -lpq: No such file or directory\n= note: /usr/bin/ld: cargo-green: add `\"libpq-dev\"` to either $CARGOGREEN_ADD_APT (or apk) or to this crate's or your root crate's [package.metadata.green.add] apt list\n"}
{"$message_type":"diagnostic","rendered":"error: environment variable `MIME_TYPES_GENERATED_PATH` not defined at compile time\n  = help: use `std::env::var(\"MIME_TYPES_GENERATED_PATH\")` to read the variable at run time\n= help: cargo-green: add `\"MIME_TYPES_GENERATED_PATH\"` to either $CARGOGREEN_SET_ENVS or to this crate's or your root crate's [package.metadata.green] set-envs list\n"}
"#]]
    );
}

/// A registry token in a rate-limit error never reaches the terminal, nor the Md.
#[test]
fn rate_limit_credentials_are_hidden() {
    let t = Tree::new();
    t.compile(Krate {
        pkg: "autocfg",
        version: "1.0.1",
        mdid: AUTOCFG,
        stderr: &["toomanyrequests: You have reached your pull rate limit as 'hubuser': dckr_jti_tookeeeennn-H0jyHY3m7bYZruA=. You may increase the limit by upgrading. https://www.docker.com/increase-rate-limit"],
        ..Default::default()
    });
    assert_snapshots_eq!(
        t.cargo.read(Stderr).join("\n"),
        snapbox::str![
            "toomanyrequests: You have reached your pull rate limit as 'hubuser': *************************************. You may increase the limit by upgrading. https://www.docker.com/increase-rate-limit"
        ]
    );
    assert!(!t.fs.read(format!("{DEBUG}/{AUTOCFG}.toml")).unwrap().contains("dckr_jti_"));
}
